export function sheetValue(
  slug: string,
  row: number,
  col: number,
): string | undefined {
  return VALUES[slug]?.[`${row}:${col}`];
}

export function sheetFormula(
  slug: string,
  row: number,
  col: number,
): string | undefined {
  return FORMULAS[slug]?.[`${row}:${col}`];
}

export function sheetInk(
  slug: string,
  row: number,
  col: number,
): string | undefined {
  return INK[slug]?.[`${row}:${col}`];
}

export function sheetImages(slug: string): SheetImage[] {
  return IMAGES[slug] ?? [];
}

export function sheetValidations(slug: string): SheetValidation[] {
  return VALIDATIONS[slug] ?? [];
}
